// Nightly cron entrypoint for client report AI summaries. Point an external
// scheduler at this (POST, 9 PM PST) with the CRON_SECRET. Auth is the secret
// only, so it is unusable until CRON_SECRET is set (safe by default).
app.post("/api/cron/generate-report-summaries", async (req, res) => {
  try {
    const secret = process.env.CRON_SECRET;
    const provided =
      req.get("x-cron-secret") || req.query.secret || req.body?.secret;
    if (!secret || provided !== secret) {
      return sendApiError(res, 401, "Unauthorized");
    }
    const result = await runDailyClientReportSummaries();
    return sendApiSuccess(res, result);
  } catch (error) {
    console.error("POST /api/cron/generate-report-summaries error:", error);
    return sendApiError(
      res,
      500,
      error.message || "Failed to generate report summaries",
    );
  }
});

// Manual single-client regenerate (internal "Regenerate" button).
app.post(
  "/api/clients/:id/report-summary/generate",
  requireDashboardAuth,
  async (req, res) => {
    try {
      const orgId = req.loggedInUser?.org_id || DASHBOARD_ORG_ID;
      const clientId = Number(req.params.id);
      if (!clientId) return sendApiError(res, 400, "Invalid client id");
      const period = CLIENT_REPORT_SUMMARY_PERIODS.includes(req.body?.period)
        ? req.body.period
        : "daily";
      // Optional week_start (YYYY-MM-DD Monday) targets a specific week's summary
      // when regenerating from a historical Week N tab. Ignored for daily.
      let weekStartMs = null;
      if (period === "weekly" && req.body?.week_start) {
        const parsed = Date.parse(`${String(req.body.week_start).slice(0, 10)}T00:00:00Z`);
        if (!Number.isNaN(parsed)) weekStartMs = mondayStartOfUtcMs(parsed);
      }
      const { data: client, error } = await supabase
        .from("clients")
        .select("id, org_id, name, company_name")
        .eq("org_id", orgId)
        .eq("id", clientId)
        .is("deleted_at", null)
        .maybeSingle();
      if (error) throw error;
      if (!client) return sendApiError(res, 404, "Client not found");
      const saved = await runClientReportSummary({
        orgId,
        client,
        period,
        userId: req.loggedInUser?.id || null,
        weekStartMs,
      });
      return sendApiSuccess(res, saved);
    } catch (error) {
      console.error(
        "POST /api/clients/:id/report-summary/generate error:",
        error,
      );
      return sendApiError(
        res,
        500,
        error.message || "Failed to generate summary",
      );
    }
  },
);

// Upsert the manually-curated Goals block for a client (staff only; the client
// sees it read-only on their external dashboard). Records who last changed it.
app.post(
  "/api/clients/:id/goals",
  requireDashboardAuth,
  async (req, res) => {
    try {
      const orgId = req.loggedInUser?.org_id || DASHBOARD_ORG_ID;
      const clientId = Number(req.params.id);
      if (!clientId) return sendApiError(res, 400, "Invalid client id");
      const rawItems = Array.isArray(req.body?.goals_json) ? req.body.goals_json : [];
      const goalsJson = rawItems
        .map((g) => ({
          title: String(g?.title ?? "").trim().slice(0, 300),
          value: String(g?.value ?? "").trim().slice(0, 100),
        }))
        .filter((g) => g.title || g.value)
        .slice(0, 100);
      const notes = String(req.body?.notes ?? "").slice(0, 20000);

      const { data: client, error: clientError } = await supabase
        .from("clients")
        .select("id")
        .eq("org_id", orgId)
        .eq("id", clientId)
        .is("deleted_at", null)
        .maybeSingle();
      if (clientError) throw clientError;
      if (!client) return sendApiError(res, 404, "Client not found");

      const now = new Date().toISOString();
      const { data: saved, error } = await supabase
        .from("client_goals")
        .upsert(
          [
            {
              org_id: orgId,
              client_id: clientId,
              goals_json: goalsJson,
              notes: notes,
              updated_by_user_id: req.loggedInUser?.id || null,
              updated_at: now,
            },
          ],
          { onConflict: "org_id,client_id" },
        )
        .select()
        .single();
      if (error) throw error;

      await insertClientActivityLog({
        orgId,
        clientId,
        actorUserId: req.loggedInUser?.id || null,
        action: "client_goals_updated",
        entityType: "client_goals",
        entityId: saved?.id || null,
      });

      return sendApiSuccess(res, saved);
    } catch (error) {
      console.error("POST /api/clients/:id/goals error:", error);
      return sendApiError(res, 500, error.message || "Failed to save goals");
    }
  },
);

