app.post(
  "/api/leads/:business/:leadId/upload-call",
  requireDashboardAuth,
  upload.single("audio"),
  async (req, res) => {
    try {
      const orgId = req.session?.user?.org_id || DASHBOARD_ORG_ID;

      const business = req.params.business;
      const leadId = Number(req.params.leadId);

      if (!req.file) {
        return res.status(400).json({
          success: false,
          error: "Audio file required",
        });
      }

      const audioUrl = await uploadLeadCallAudio(
        req.file.buffer,
        req.file.originalname,
      );

      let transcript = "";

      if (openai) {
        const tempPath = path.join(
          os.tmpdir(),
          `${Date.now()}-${req.file.originalname}`,
        );

        fs.writeFileSync(tempPath, req.file.buffer);

        const transcription = await openai.audio.transcriptions.create({
          file: fs.createReadStream(tempPath),
          model: "whisper-1",
        });

        transcript = transcription.text || "";

        fs.unlinkSync(tempPath);
      }

      const { data, error } = await supabase
        .from("lead_calls")
        .insert({
          org_id: orgId,
          business,
          lead_id: leadId,
          audio_url: audioUrl,
          transcript,
          created_by: req.session?.user?.name || "Unknown",
        })
        .select()
        .single();

      if (error) {
        throw error;
      }

      return res.json({
        success: true,
        call: data,
      });
    } catch (error) {
      console.error("Upload call failed:", error);

      return res.status(500).json({
        success: false,
        error: error.message,
      });
    }
  },
);

