// Delete a single client lead.
app.delete(
  "/api/clients/:id/leads/:leadId",
  requireDashboardAuth,
  async (req, res) => {
    try {
      const orgId = req.loggedInUser?.org_id || DASHBOARD_ORG_ID;
      const actorUserId = req.loggedInUser?.id || null;
      const clientId = Number(req.params.id);
      const leadId = Number(req.params.leadId);

      if (!clientId || !leadId) {
        return sendApiError(res, 400, "Invalid client or lead id");
      }

      const business = await resolveClientLeadBusiness(orgId, clientId);
      const { tableName: leadTable, clientId: leadClientId } =
        resolveLeadSource(business);
      let deleteQuery = supabase
        .from(leadTable)
        .delete()
        .eq("org_id", orgId)
        .eq("id", leadId);
      if (leadClientId) deleteQuery = deleteQuery.eq("client_id", leadClientId);

      const { data, error } = await deleteQuery.select("*").maybeSingle();

      if (error) throw error;
      if (!data) return sendApiError(res, 404, "Lead not found");

      await insertClientActivityLog({
        orgId,
        clientId,
        actorUserId,
        action: "client_lead_deleted",
        entityType: leadTable,
        entityId: leadId,
        oldValue: data,
      });

      return sendApiSuccess(res, { id: leadId });
    } catch (error) {
      console.error("DELETE /api/clients/:id/leads/:leadId error:", error);
      return sendApiError(
        res,
        error.statusCode || 500,
        error.message || "Failed to delete lead",
      );
    }
  },
);

// Make the client workspace "Linked Tasks" actionable. These are org-wide tasks
// whose free-text `business` names this client; we allow quick inline edits
// (status / priority / progress) and mirror each change into task_history so the
// edit is consistent with the rest of the command-driven task system.
app.patch(
  "/api/clients/:id/linked-tasks/:taskId",
  requireDashboardAuth,
  async (req, res) => {
    try {
      const orgId = req.loggedInUser?.org_id || DASHBOARD_ORG_ID;
      const actorUserId = req.loggedInUser?.id || null;
      const clientId = Number(req.params.id);
      const taskId = Number(req.params.taskId);
      const body = req.body || {};

      if (!clientId || !taskId) {
        return sendApiError(res, 400, "Invalid client or task id");
      }

      // Authorize: the task must actually be linked to this client — its
      // free-text `business` must equal the client's name or company name (the
      // same rule the Linked Tasks list uses to surface it).
      const { data: client, error: clientError } = await supabase
        .from("clients")
        .select("name, company_name")
        .eq("org_id", orgId)
        .eq("id", clientId)
        .eq("is_active", true)
        .is("deleted_at", null)
        .maybeSingle();
      if (clientError) throw clientError;
      if (!client) return sendApiError(res, 404, "Client not found");

      const { data: task, error: taskError } = await supabase
        .from("tasks")
        .select("id, business, status, priority, progress, blocker_note")
        .eq("org_id", orgId)
        .eq("id", taskId)
        .maybeSingle();
      if (taskError) throw taskError;
      if (!task) return sendApiError(res, 404, "Task not found");

      const clientNameKeys = new Set(
        [client.name, client.company_name]
          .filter(Boolean)
          .map((s) => String(s).trim().toLowerCase()),
      );
      if (
        !clientNameKeys.has(String(task.business || "").trim().toLowerCase())
      ) {
        return sendApiError(res, 403, "Task is not linked to this client");
      }

      const patch = {
        last_updated_by_user_id: actorUserId,
        updated_at: new Date().toISOString(),
      };
      const historyCalls = [];

      if (body.status !== undefined) {
        const status = normalizeText(body.status || "");
        if (!["open", "in_progress", "blocked", "done"].includes(status)) {
          return sendApiError(res, 400, "Invalid status");
        }
        patch.status = status;
        // Mirror the command system's status side effects.
        if (status === "done") patch.progress = 100;
        if (status === "open" && Number(task.progress) === 100)
          patch.progress = 0;
        if (task.blocker_note && status !== "blocked")
          patch.blocker_note = null;
        historyCalls.push([
          "status_change",
          "status",
          { status: task.status, progress: task.progress },
          { status, progress: patch.progress ?? task.progress },
        ]);
      }

      if (body.priority !== undefined) {
        const priority = normalizeText(body.priority || "");
        if (!["low", "medium", "high", "urgent"].includes(priority)) {
          return sendApiError(res, 400, "Invalid priority");
        }
        patch.priority = priority;
        historyCalls.push(["edit", "priority", task.priority, priority]);
      }

      if (body.progress !== undefined) {
        let progress = Math.round(Number(body.progress));
        if (!Number.isFinite(progress)) {
          return sendApiError(res, 400, "Invalid progress");
        }
        progress = Math.max(0, Math.min(100, progress));
        patch.progress = progress;
        historyCalls.push([
          "progress_change",
          "progress",
          { progress: task.progress, status: task.status },
          { progress, status: patch.status ?? task.status },
        ]);
      }

      // Visibility toggle: whether this task shows on the client's external
      // dashboard. Not a task-content change, so it is not logged to history.
      if (body.is_client_visible !== undefined) {
        patch.is_client_visible =
          body.is_client_visible === true || body.is_client_visible === "true";
      }

      if (historyCalls.length === 0 && body.is_client_visible === undefined) {
        return sendApiError(res, 400, "No editable fields provided");
      }

      const { data: updated, error: updateError } = await supabase
        .from("tasks")
        .update(patch)
        .eq("org_id", orgId)
        .eq("id", taskId)
        .select("id, status, priority, progress, is_client_visible")
        .maybeSingle();
      if (updateError) throw updateError;
      if (!updated) return sendApiError(res, 404, "Task not found");

      for (const [changeType, field, oldValue, newValue] of historyCalls) {
        await insertTaskHistory(
          taskId,
          actorUserId,
          changeType,
          field,
          oldValue,
          newValue,
          orgId,
        );
      }

      return sendApiSuccess(res, updated);
    } catch (error) {
      console.error(
        "PATCH /api/clients/:id/linked-tasks/:taskId error:",
        error,
      );
      return sendApiError(res, 500, error.message || "Failed to update task");
    }
  },
);

